INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Common Area Maintenance Charges', '2', '1', 'DE LOS SERVICIOS', E'- HEXA will provide the following services:\n  - Maintenance and cleaning of reception, bathrooms, windows, facades, gardening, and trash removal.\n  - Security, surveillance, operation, and management.\n  - Handling and repair of operational equipment.\n  - Monitoring and maintenance of the hydraulic system.\n  - All services are for the common areas of the property only.\n- Measurement and billing for water or similar services.\n- Use of advertising space on a Totem.\n\n- A monthly maintenance fee will be charged for these services, equal to 10% of the current monthly rent.', E'HEXA se obliga a prestar los siguientes servicios:\nA. i) gastos de mantenimiento y limpieza de recepción, baños, cancelería, vidrios y fachadas, jardinería y retiro de basura .\nii) seguridad, vigilancia, funcionamiento y administración.\niii) manejo y reparación de equipos operativos.\niv) monitoreo y mantenimiento del sistema hidráulico.\nTodo lo anterior, exclusivamente de las áreas comunes del inmueble.\nB. Medición cobro de agua o cualquier otro servicio análogo.\nC. Uso de espacio publicitario en Totem.\n\nPor los servicios descritos se pagará una cuota de mantenimiento mensual, la cual siempre será equivalente al 10% de la Renta mensual vigente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Security Deposit', '8', 'Décima primera', 'DEPÓSITO EN GARANTÍA', E'- The Tenant must give the Landlord a security deposit equal to 1 month''s rent within 7 days after the premises are delivered.\n- The security deposit will increase in line with any increases in the monthly rent.', E'El Arrendatario se obliga a entregar al Arrendador, dentro de los 7 (siete) días naturales posteriores a la Fecha de Entrega del Local, 1 mes de renta por concepto de depósito en Garantía \n\nEl Depósito en Garantía deberá incrementarse en los mismos términos que la Renta Mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Parking', '12', 'Vigésima tercera', 'ESTACIONAMIENTO', E'- Customers of the Tenant can use the parking area with a special rate of $10.00 for the first 2 hours or 4% of the classic membership value.\n- If the Landlord increases the general parking cost, the special rate can only be adjusted by the same percentage applied to the $10.00 base rate.\n- Rounding rules for adjustments:\n  - $0.01 to $0.49: Round down, but accumulate until reaching $0.50 or more, then round up.\n  - $0.50 to $0.99: Round up.\n- The Tenant must purchase and install necessary equipment to ensure the proper use of the special rate before the store opens, at their own expense.\n- The Landlord will provide 6 free parking passes for the Tenant''s staff.', E'Las partes acuerdan que los usuarios o clientes del Arrendatario podrán hacer uso del área de estacionamiento, por lo que se otorga una tarifa preferencial para clientes de $10.00 por las primeras 2 horas o bien el equivalente al 4% del valor de la membresía clásica.\n\nEn caso de que el Arrendador decida incrementar el costo general del estacionamiento del Centro Comercial, la tarifa preferencial podrá ajustarse únicamente en el mismo porcentaje aplicado sobre la tarifa base de $10.00.\n\nEl monto resultante del ajuste será redondeado de acuerdo con las siguientes reglas:\ni) Si los centavos resultantes son de $0.01 a $0.49, se redondearán a la baja. No obstante, dichos centavos se acumularán en los cálculos subsecuentes hasta alcanzar un total de $0.50 o más, momento en el cual se redondeará al alza. \nii) Si los centavos resultantes son de $0.50 a $0.99, se redondeará al alza.\n\nel Arrendatario realizará a su costa la compra del equipo e implementaciones necesarias que garanticen el correcto uso de esta tarifa preferencial previo a la apertura del Local Comercial ("validadora") durante la vigencia del presente Contrato y sus prórrogas. Además, el Arrendador se obliga a otorgar, sin costo, 6 (seis) pensiones para uso del personal del Arrendatario');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Condición suspensiva', '13', 'Trigésima', 'CONDICIÓN SUSPENSIVA', E'- The contract is about a future project and requires certain permits to start building a shopping center.\n- The lease agreement will only become effective if certain conditions are met:\n  1. Both parties must agree in writing on an insurance policy covering the tenant''s goods and contents in the premises.\n  2. The landlord must complete the demolition of existing structures on the property.\n  3. The landlord must obtain construction permits for the shopping center.\n  4. The landlord must obtain authorization for the use and occupancy of the shopping center.\n- If conditions 2, 3, and 4 are not met by December 31, 2030, the contract will be void.\n- The contract can be voided without a court declaration, simply by the landlord notifying the tenant in writing.', E'toda vez que las Partes reconocen que el presente Contrato versa sobre cosa futura y para poder iniciar la construcción del Centro Comercial se requiere de la obtención de diversos permisos emitidos por la autoridad competente, las Partes acuerdan que para que entre en vigor el presente Contrato de Arrendamiento quedara sujeto a una condición suspensiva, que consiste en lo siguiente:\nI) Que las Partes lleguen a un acuerdo por escrito respecto de la Póliza de seguro que cubra los bienes EFICIENTE mercancías y contenidos del Arrendatario en el Local, referida en la Cláusula Decima Novena.\nII) Que el Arrendador concluya la demolición total de las construcciones actuales que se ubican en el predio III)Que el Arrendador obtenga la autorización de la manifestación de construcción para edificar el Centro Comercial. \nIV) Que el Arrendador obtenga la autorización del uso y ocupación del Centro Comercial.\n\nEn caso de que las condiciones suspensivas referidas en los incisos (ii), (iii) y (iv) no sean cumplidas a más tardar el 31 de diciembre de 2030, de conformidad con lo establecido en el presente Contrato, éste quedará sin efectos. Lo anterior, sin necesidad de declaración judicial, únicamente mediante la simple notificación escrita que entregue el Arrendador al Arrendatario, la cual surtirá efectos al momento.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('24c8b1d9-6742-41fa-82a9-ac0a2fe2b160', 'Late Fees', '2', 'Primera', 'DEFINICIONES', E'- The amount is calculated daily.\n- It is based on the 28-day Interbank Equilibrium Interest Rate (TIIE).\n- The rate is determined by the Bank of Mexico.\n- It is published in the Official Gazette of the Federation.\n- An additional 6 points are added to the rate.', 'Significa la cantidad equivalente calculada diariamente con base en la Tasa de Interés Interbancaria de Equilibrio (TIIE) a 28 (veintiocho) días determinada por el Banco de México y publicada en el Diario Oficial de la Federación más 6 (seis) puntos.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('10042b99-3efb-4105-a651-1ca9942ee8d8', 'Paseo La Fe', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '200 Avenida Miguel Alemán', 'PC-A-02', 'San Nicolás De Los Garza', 'MX-NLE', '66477', 'MX', '200 Avenida Miguel Alemán, PC-A-02, San Nicolás De Los Garza, MX-NLE 66477', 25.719736, -100.219498, 'Retail', 'Lifestyle Center', 'Fitness', 'Franchise', 'Power Center Paseo La Fe', 2289.27, NULL, NULL, '{"map_lease_expiration_date":"2037-01-12","map_marker_color":"#808080","coordinate":"rooftop|25.7197360000|-100.2194980000|accurate","city_state":"San Nicolás De Los Garza, MX-NLE","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"390 Calle Paricutín, Monterrey, MX-NLE 64700","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2042-01-12","lease_expiration_date":"2037-01-12","lease_renewal_notice":"3 Months Prior","lease_length_in_months_remaining":123,"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":68150,"grid_name":"Paseo La Fe","grid_full_address":"200 Avenida Miguel Alemán, PC-A-02, San Nicolás De Los Garza, MX-NLE 66477","map_addr_1":"200 Avenida Miguel Alemán","map_addr_2":"PC-A-02","map_city_state_zip":"San Nicolás De Los Garza, MX-NLE 66477","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2026-06-01 19:49:20","active_lease_count_over_time":61537,"location_count_over_time":68150,"remaining_rent_liability_over_time":61537}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('0ff1501a-a930-456e-b96b-fc7a2ec81d23', '10042b99-3efb-4105-a651-1ca9942ee8d8', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Paseo La Fe Lease: Habitación y Promoción Inmobiliaria S.A. de C.V. (01/13/2027 - 01/12/2037)', 'Not sure', false, 'vencido', 'Lease', NULL, '2027-01-13', '2026-08-31', '2037-01-12', '2042-01-12', false, 1, NULL, 1, NULL, NULL, '2036-10-12', NULL, 119, 'Habitación y Promoción Inmobiliaria S.A. de C.V.', NULL, NULL, '390 Calle Paricutín', NULL, 'Monterrey', 'MX-NLE', '64700', 'MX', 'Juan Francisco Caceres Villareal y Mayte Berenice Ruvalcaba Garcia', NULL, 'mayte.ruvalcaba@alteadesarrollos.com', 135, 'percent', NULL, NULL, 1201866.75, E'La Arrendataria se obliga a pagar a la Arrendadora por concepto de rentas adelantadas la cantidad de $1,201,866.75 M.N. (un millón doscientos unos mil ochocientos sesenta y seis pesos 75/100 moneda nacional), más el impuesto al valor agregado cantidad equivalente a 3 (tres) meses de Renta Mensual, las cuales serán pagadas conforme al siguiente calendario de pagos:\nA) El primer pago equivalente a una mensualidad por la cantidad de $400,622.25M.N. (cuatrocientos mil seiscientos veintidós pesos 25/100 moneda nacional) más IVA, a más tardar 15 (quince) días posteriores a la firma del presente contrato. \nB) El segundo pago equivalente a dos mensualidades equivalentes a la cantidad de $801,244.50 M.N. (ochocientos unos mil doscientos cuarenta y cuatro pesos 50/100 Moneda Nacional) más IVA, a más tardar 15 (quince) días posteriores a la fecha de firma del Acta de Entrega del Local. \n\nDichos pagos deberán ser realizados via transferencia electrónica a la cuenta a nombre de la Arrendadora que fue señalada en la carátula del presente contrato. Las Partes acuerdan que las mensualidades adelantadas, serán tomadas y aplicadas después del periodo de gracia en los primeros 3 (tres) meses. \n\nLa Arrendadora se obliga a entregar por cada uno de los pagos que la Arrendataria vaya a efectuar, el comprobante fiscal digital y archivo XML correspondientes, el cual deberá de cumplir con todos los requisitos fiscales correspondientes, mismo que tendrá que ser entregado y enviado vía correo electrónico a los siguientes correos: fpt_arrendamiento@fpt.com.mx por lo menos cinco (5) días antes al pago respectivo para su trámite, sin el cual no se generará la obligación de pago de renta.', 5208089.25, true, '{"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"is_next_percent_rent_payment":"No"}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('0ff1501a-a930-456e-b96b-fc7a2ec81d23', 'Domicilio del Contrato', 'PASEO LA FE, específicamente en el área comercial denominada Power Center (en lo sucesivo "Centro Comercial"), ubicado en Avenida Miguel Alemán número 200, entre las calles Av. Las Torres y Rómulo Garza, municipio de San Nicolás de los Garza, Nuevo León, C.P. 66473. Local número PC-A-02, ubicado en el área denominada Power Center señalado en el Apartado inmediato anterior.', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('0ff1501a-a930-456e-b96b-fc7a2ec81d23', 'Fecha de Firma del Contrato', '11 de febrero 2026', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0ff1501a-a930-456e-b96b-fc7a2ec81d23', 'Condition precedent', '4', 'Primera Bis', 'CONDICIÓN SUSPENSIVA', E'- The contract will only be effective if the following condition is met: The landlord must sign a Parking Use Agreement within 2 months of signing this contract.\n- The deadline can be extended if both parties agree in writing.\n- If the condition cannot be met due to reasons beyond the landlord''s control, the contract can be terminated without any liability for either party.\n- In such a case, the landlord must refund any payments received to the tenant within 15 business days of the termination notice, and both parties will be free from any further obligations.', 'Las partes convienen que el presente contrato surtirá efectos siempre y cuando se cumpla la siguiente condición: a) Que la Arrendadora firme un Convenio de Convivencia para el uso de estacionamiento en un plazo de 2 (dos) meses posteriores a la fecha de firma del presente Contrato. No obstante, las Partes acuerdan que dicho plazo podrá prorrogarse previo acuerdo por escrito entre ambas Partes. En caso de que no se pueda cumplir la condición suspensiva por causas ajenas a la Arrendadora, las partes podrán dar por terminado el contrato sin responsabilidad alguna para las partes. En tal supuesto, la Arrendadora deberá reintegrar a la Arrendataria, dentro de los 15 (quince) días hábiles siguientes a la notificación de terminación, cualquier cantidad que hubiere recibido con motivo del presente Contrato, quedando ambas Partes liberadas de cualquier obligación adicional.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0ff1501a-a930-456e-b96b-fc7a2ec81d23', 'Incremento de Renta', '5', 'Quinta', 'AJUSTE DE LA RENTA', E'- The adjustment will be based on the change in the National Consumer Price Index (INPC) published monthly by INEGI.\n- The comparison will be between the INPC two months before the signing date and two months before the adjustment date.\n- If the annual INPC increase is unusually high, both parties agree to review and negotiate a new increase percentage in good faith.', 'Se tomará como base el porcentaje que haya variado el Índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores a la fecha de firma del presente instrumento y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste. Las Partes acuerdan que, si el incremento anual del Índice Nacional de Precios al Consumidor (INPC) experimente una variación atípica, las partes se obligan a revisar y negociar de buena fe el nuevo porcentaje de incremento a aplicar.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('0ff1501a-a930-456e-b96b-fc7a2ec81d23', 'Parking', '10', 'Décima primera', 'OBLIGACIONES DE LA ARRENDATARIA', E'- The landlord must maintain at least 100 parking spaces at Paseo La Fe for use by both their customers and the tenant''s customers.\n- The landlord must comply with parking space requirements set by applicable laws for Paseo La Fe.\n- The landlord will offer the tenant''s customers a discounted parking rate: $10 for the first 120 minutes and $15 for each additional hour.\n- The tenant must purchase an annual policy from the landlord''s parking equipment and systems provider at their own expense.\n- The landlord must install a parking payment machine near the tenant''s premises.\n- The landlord will provide 3 free parking passes for the tenant''s staff, usable at any time.', 'La Arrendadora será responsable de contar y mantener, en todo momento, un mínimo de 100 (cien) cajones de estacionamiento dentro del complejo comercial Paseo La Fe no exclusivos para uso de sus usuarios/clientes, así como de los usuarios/clientes de la Arrendataria, y de cumplir permanentemente con el número de cajones de estacionamiento exigidos por la legislación aplicable al Complejo Comercial Paseo La Fe. La Arrendadora permitirá a los usuarios/clientes de la Arrendataria el uso del área de su estacionamiento, otorgándoles una tarifa preferencial de $10.00 (diez pesos M.N.) por los primeros ciento veinte (120) minutos, y de $15.00 (quince pesos M.N.) por cada fracción subsecuente de hora. La Arrendataria contratará, por su cuenta y costo, una póliza anual directamente con el proveedor de equipos y sistemas de control de estacionamiento de la Arrendadora. Asimismo, la Arrendadora deberá instalar un cajero para el cobro de estacionamiento dentro de las áreas comunes cercanas al Local objeto del presente Contrato. La Arrendadora se obliga a otorgar, sin costo alguno, 3 (tres) pensiones para uso del personal de la Arrendataria, válidas en cualquier horario.');
